@staticmethod
def _normalize_batch_input(
    input_: list[dict[str, Any]] | dict[str, Any],
) -> tuple[dict[str, Any], Any | None]:
    """Normalize list/dict batch input to a single batched dict.

    Returns ``(batched_input, meta)`` where ``meta`` is non-None only when
    input is list-based and can be used to split forward outputs back into
    per-trajectory results.
    """
    if isinstance(input_, list):
        return concat_batch(input_)
    return input_, None

def _get_model_name_parameters(
    self, meta: WeightUpdateMeta
) -> Iterator[tuple[str, nn.Parameter]]:
    name_params_iterator = self.model.named_parameters()
    if self.is_vision_model and is_qwen_vl_model(self.model_config.model_type):
        for name, value in name_params_iterator:
            if meta.gen_allocation.backend == "sglang":
                # SGLang 0.5.9 branch
                # LLM part: "model.language_model.norm.weight" -> "model.norm.weight"
                # Vision part: "model.visual.blocks.5.mlp.gate_proj.weight" -> "visual.blocks.5.mlp.gate_proj.weight"
                new_name = name.replace("language_model.", "", 1)
                if new_name.startswith("model.visual."):
                    new_name = new_name.replace("model.", "", 1)
                yield new_name, value
                continue
            # vLLM 0.17.0 branch
            new_name = name.replace("model.", "", 1)
            if new_name.startswith("language_model."):
                new_name = new_name.replace(
                    "language_model.", "language_model.model.", 1
                )
            elif new_name.startswith("lm_head."):
                new_name = f"language_model.{new_name}"
            yield new_name, value
    elif self.is_vision_model and is_gemma3_model(self.model_config.model_type):
        for name, value in name_params_iterator:
            new_name = name.replace("model.", "", 1)
            if new_name.startswith("language_model."):
                new_name = new_name.replace(
                    "language_model.", "language_model.model.", 1
                )
            elif new_name.startswith("lm_head."):
                new_name = new_name.replace(
                    "lm_head.", "language_model.lm_head.", 1
                )
            yield new_name, value
    else:
        yield from name_params_iterator

def _compute_dtype(self) -> torch.dtype:
    """Resolve config.dtype to torch.dtype (canonicalized in TrainEngineConfig)."""
    return getattr(torch, self.config.dtype)

def _cast_to_compute_dtype(self, tensor: torch.Tensor) -> torch.Tensor:
    """Cast fp32 master storage to compute dtype for export / rollout sync.

    When optimizer_dtype=float32 (the fp32 master weights default), the
    underlying storage is fp32. HF export and xccl weight sync to rollout
    engines (SGLang/vLLM) must cast back to compute dtype (typically bf16)
    so deployment artefacts and broadcast bandwidth stay unchanged.
    No-op when storage already matches compute dtype.
    """
    compute_dtype = self._compute_dtype()
    if tensor.is_floating_point() and tensor.dtype != compute_dtype:
        return tensor.to(compute_dtype)
    return tensor

def _get_full_tensor(self, param: nn.Parameter) -> torch.Tensor:
    """Get full tensor from a parameter, handling DTensor and CPU offloaded tensors."""
    tensor = param.data
    if isinstance(tensor, DTensor):
        # For non-offloaded DTensor, directly call full_tensor()
        if tensor.device.type != "cpu":
            return tensor.full_tensor()

        # Handle CPU offloaded DTensor: reconstruct DTensor from local tensor
        temp_dtensor = DTensor.from_local(
            tensor.to_local(),
            device_mesh=tensor.device_mesh,
            placements=tensor.placements,
        )
        return temp_dtensor.full_tensor()
    else:
        if tensor.device.type == "cpu":
            tensor = tensor.to(current_platform.device_type)
        return tensor

def _update_bucket_weights_from_distributed_async(
    self,
    meta: WeightUpdateMeta,
    named_tensors: list[tuple[str, nn.Parameter | torch.Tensor]],
    stream: torch.cuda.Stream | None = None,
) -> _PendingWeightUpdateBucket | None:
    # Early exit when chunk size is relatively small
    if not named_tensors:
        return None

    param_specs = [
        ParamSpec(
            name=name,
            shape=tuple(tensor.shape),
            dtype=str(tensor.dtype).split("torch.")[1],
        )
        for name, tensor in named_tensors
    ]

    if self.config.use_lora:
        if not self.config.target_modules or self.config.target_modules == [
            "all-linear"
        ]:
            target_modules = "all-linear"
        else:
            target_modules = self.config.target_modules

        meta.peft_config = {
            "r": self.config.lora_rank,
            "lora_alpha": self.config.lora_alpha,
            "target_modules": target_modules,
            "bias": "none",
        }

    if len(self.weight_update_groups) > 1:
        # Per-PP-rank groups: broadcast to each group sequentially.
        # Each group's NCCL broadcast must complete before the next
        # starts, because sglang's PP event loop processes requests
        # serially within each PP rank.
        for group_name, group in zip(
            self.weight_update_group_names, self.weight_update_groups
        ):
            pp_meta = copy.copy(meta)
            pp_meta.nccl_group_name = group_name
            fut = self.rollout_engine.update_weights_from_distributed(
                pp_meta, param_specs
            )
            for _, tensor in named_tensors:
                dist.broadcast(tensor, src=0, group=group, async_op=False)
            fut.result()
        # Return a no-op bucket (all work is already done).
        _done_fut: Future = Future()
        _done_fut.set_result(None)
        return _PendingWeightUpdateBucket(
            handles=[],
            fut=_done_fut,
            named_tensors=named_tensors,
            stream=stream,
        )

    # Single group: original async path
    fut = self.rollout_engine.update_weights_from_distributed(meta, param_specs)

    handles = []
    if stream is not None:
        stream.wait_stream(torch.cuda.current_stream())
        context = torch.cuda.stream(stream)
    else:
        context = nullcontext()

    with context:
        for _, tensor in named_tensors:
            handles.append(
                dist.broadcast(
                    tensor,
                    src=0,
                    group=self.weight_update_groups[0],
                    async_op=True,
                )
            )

    return _PendingWeightUpdateBucket(
        handles=handles,
        fut=fut,
        named_tensors=named_tensors,
        stream=stream,
    )

def _wait_pending_weight_update_bucket(
    self, pending_bucket: _PendingWeightUpdateBucket | None
):
    if pending_bucket is None:
        return

    for handle in pending_bucket.handles:
        handle.wait()

    pending_bucket.fut.result()
    pending_bucket.named_tensors.clear()

def _update_bucket_weights_from_distributed(
    self,
    meta: WeightUpdateMeta,
    named_tensors: list[tuple[str, nn.Parameter | torch.Tensor]],
):
    pending_bucket = self._update_bucket_weights_from_distributed_async(
        meta, named_tensors
    )
    self._wait_pending_weight_update_bucket(pending_bucket)

def _init_weight_update_from_distributed(self, meta: WeightUpdateMeta):
    assert meta.type == "xccl"

def parse_score_response(
    self, response: dict[str, Any], target_len: int
) -> list[float]:
    meta_info = response.get("meta_info")
    if meta_info is None:
        raise ValueError("SGLang response missing meta_info for score request")
    # SGLang returns [logprob, token_id, ...]
    all_logprobs = [float(x[0]) for x in meta_info.get("input_token_logprobs", [])]
    if len(all_logprobs) < target_len:
        raise ValueError(
            f"SGLang returned insufficient input_token_logprobs: {len(all_logprobs)} < {target_len}"
        )
    return all_logprobs[-target_len:]

def build_disk_weight_update_requests(
    self, meta: WeightUpdateMeta
) -> WeightUpdateRequests:
    """Build SGLang disk weight update requests."""
    if meta.use_lora:
        if not meta.lora_name:
            raise ValueError("LoRA name is required for LoRA update.")
        if meta.version is None:
            raise ValueError("Version is required for LoRA update.")
        lora_name = get_versioned_lora_name(meta.lora_name, meta.version)
        # Load new LoRA (best_effort: if already registered, SGLang
        # returns 400 which is silently ignored).
        requests = [
            HttpRequest(
                endpoint="/load_lora_adapter",
                payload={"lora_name": lora_name, "lora_path": str(meta.path)},
                best_effort=True,
            ),
        ]
        # Unload the version that has fallen outside the retention window so
        # sglang does not accumulate one adapter per train step (which leaks
        # VRAM and eventually hangs). Kept versions cover off-policy rollouts
        # (max_head_offpolicyness). Best-effort: the stale adapter may have
        # already been evicted or never loaded.
        keep = meta.lora_keep_versions
        if keep > 0 and meta.version - keep >= 0:
            stale_name = get_versioned_lora_name(
                meta.lora_name, meta.version - keep
            )
            requests.append(
                HttpRequest(
                    endpoint="/unload_lora_adapter",
                    payload={"lora_name": stale_name},
                    best_effort=True,
                )
            )
        return WeightUpdateRequests(requests=requests)
    else:
        # Full model update
        return WeightUpdateRequests(
            requests=[
                HttpRequest(
                    endpoint="/update_weights_from_disk",
                    payload={
                        "model_path": str(meta.path),
                        "abort_all_requests": True,
                    },
                )
            ]
        )

def build_distributed_weight_update_requests(
    self, meta: WeightUpdateMeta, param_specs: list[ParamSpec]
) -> WeightUpdateRequests:
    """Build SGLang distributed weight update requests.

    Note: SGLang distributed weight update (NCCL-based) does not support LoRA.
    For LoRA weight updates with SGLang, use disk-based update mode instead.
    """
    if meta.use_lora:
        raise ValueError(
            "SGLang distributed (XCCL/NCCL) weight update does not support LoRA. "
            "Use weight_update_mode='disk' for LoRA weight updates with SGLang."
        )
    return WeightUpdateRequests(
        requests=[
            HttpRequest(
                endpoint="/update_weights_from_distributed",
                payload={
                    "names": [pspec.name for pspec in param_specs],
                    "dtypes": [pspec.dtype for pspec in param_specs],
                    "shapes": [pspec.shape for pspec in param_specs],
                    "group_name": meta.nccl_group_name,
                    "abort_all_requests": True,
                },
            )
        ]
    )

def build_init_weights_group_request(
    self, addr: str, server_idx: int, meta: WeightUpdateMeta
) -> HttpRequest:
    """Build SGLang init weights group request.

    Supports two scenarios:

    1. **PP=1** (original): Single NCCL group spanning all TP workers across
       all DP instances. ``rank_offset`` is based on ``tp_size``.

    2. **PP>1, per-PP-rank groups**: The training engine creates a separate
       NCCL group per PP stage. The group name encodes the PP rank
       (e.g., ``update_weight_group_0``). Only sglang workers at that PP
       rank participate, so ``rank_offset`` is based on ``tp_size`` only,
       ``world_size = n_servers * tp_size + 1``, and ``pp_rank`` is
       included in the payload.

    All three training engines (Megatron, FSDP, Archon) use per-PP-rank
    group naming (``update_weight_group_{pp_rank}``) when PP>1, so the
    per-PP-rank path is always taken for PP>1.
    """
    assert meta.gen_allocation is not None
    gen_parallel = meta.gen_allocation.parallel
    group_name = meta.nccl_group_name

    # Determine if training side uses per-PP-rank groups.
    # Per-PP-rank groups are identified by group names ending with _{digit}
    # and pp_size > 1. All engines use this pattern when PP>1.
    per_pp_groups = False
    if gen_parallel.pp_size > 1:
        try:
            _suffix = group_name.rsplit("_", 1)[-1]
            int(_suffix)
            per_pp_groups = True
        except (ValueError, IndexError):
            per_pp_groups = False

    if per_pp_groups:
        # Scenario 2: PP>1 with per-PP-rank groups.
        # Extract pp_rank from the group name suffix.
        pp_rank = int(group_name.rsplit("_", 1)[-1])

        tp_size = gen_parallel.tp_size
        pp_size = gen_parallel.pp_size
        # gen_parallel.world_size = dp_size * tp_size * pp_size on the
        # inference side. n_servers (number of sglang server replicas)
        # therefore equals dp_size whether or not DP-attention is

    @property
    def ep_size(self) -> int:
        return self._ps.ep_size

    @property
    def etp_size(self) -> int:
        return self._ps.etp_size

    @property
    def dp_group(self) -> ProcessGroup:
        return self.world_mesh["dp"].get_group()

    @property
    def sp_group(self) -> ProcessGroup:
        return self.world_mesh["sp"].get_group()

    @property
    def tp_group(self) -> ProcessGroup:
        return self.world_mesh["tp"].get_group()

    @property
    def gradient_div_factor(self) -> int:
        # This is needed for FSDP-sharded experts when Expert Parallel is enabled.
        # Although the FSDP sharding of experts is done on a mesh of a different size than
        # other parameters, the gradient division factor should be consistent with data.
        return self._ps.dp_size * self._ps.cp_size

    @property
    def context_and_model_parallel_size(self) -> int:
        return self._ps.cp_size * self._ps.tp_size

    @property
    def seq_len_divisor(self) -> int:
        # 1. Sequence Parallel requires that seq_len be divisible by TP degree.
        # 2. Ulysses Sequence Parallel requires that seq_len be divisible by SP degree.
        return self._ps.tp_size * self._ps.cp_size


def apply_non_moe_tp(
    model: nn.Module,
    model_config: PretrainedConfig,
    parallel_helper: ParallelHelper,
    tp_device_mesh: DeviceMesh,
):
    num_attention_heads: int
    num_key_value_heads: int
    try:
        num_attention_heads, num_key_value_heads = (
            model.config.num_attention_heads,  # type: ignore
            model.config.num_key_value_heads,  # type: ignore
        )
    except AttributeError:
        num_attention_heads, num_key_value_heads = (
            model.config.text_config.num_attention_heads,  # type: ignore
            model.config.text_config.num_key_value_heads,  # type: ignore
        )

    tensor_parallel_size = parallel_helper.tp_size

    if (
        num_attention_heads % tensor_parallel_size != 0
        or num_key_value_heads % tensor_parallel_size != 0
    ):
        raise ValueError(
            f"num_attention_heads {num_attention_heads} and num_key_value_heads {num_key_value_heads} must be divisible by tensor_parallel_size {tensor_parallel_size}"
        )

    if not isinstance(model.model, nn.Module):
        raise RuntimeError("Model does not have the required submodule 'model'.")

    # For model or model.language_model
    model_tp_plan: dict[str, ParallelStyle] = {
        "embed_tokens": RowwiseParallel(
            input_layouts=Replicate(),
            output_layouts=Shard(1),
            use_local_output=False,
        ),
        "layers.*.input_layernorm": SequenceParallel(),
        # All-gather
        "layers.*.self_attn": PrepareModuleInput(
            input_kwarg_layouts={"hidden_states": Shard(1)},
            desired_input_kwarg_layouts={"hidden_states": Replicate()},
        ),
        "layers.*.self_attn.q_proj": ColwiseParallel(),
        "layers.*.self_attn.k_proj": ColwiseParallel(),
        "layers.*.self_attn.v_proj": ColwiseParallel(),
        # special q/k norm for qwen3
        "layers.*.self_attn.q_norm": ReplicateParallel(),
        "layers.*.self_attn.k_norm": ReplicateParallel(),
        # Reduce in RowwiseParallel, Scatter by Shard(1)
        "layers.*.self_attn.o_proj": RowwiseParallel(
            output_layouts=Shard(1),
            use_local_output=False,
        ),
        "layers.*.post_attention_layernorm": SequenceParallel(),
        "norm": SequenceParallel(),
    }

    if not is_moe_model(model_config.model_type):
        model_tp_plan.update(
            {
                # All-gather
                "layers.*.mlp": PrepareModuleInput(
                    input_layouts=Shard(1),
                    desired_input_layouts=Replicate(),
                ),
                "layers.*.mlp.gate_proj": ColwiseParallel(),
                "layers.*.mlp.up_proj": ColwiseParallel(),
                # Reduce in RowwiseParallel, Scatter by Shard(1)
                "layers.*.mlp.down_proj": RowwiseParallel(
                    output_layouts=Shard(1),
                    use_local_output=False,
                ),
            }
        )

    if is_gemma3_model(model_config.model_type):
        model_tp_plan.update(
            {
                "layers.*.pre_feedforward_layernorm": SequenceParallel(),
                "layers.*.post_feedforward_layernorm": SequenceParallel(),
            }
        )

    # For root module
    root_tp_plan: dict[str, ParallelStyle] = {}
    if hasattr(model, "lm_head") and isinstance(model.lm_head, nn.Module):
        # Implicitly all-gather in ColwiseParallel
        # Output is sharded on the last dimension (Shard(2))
        root_tp_plan["lm_head"] = ColwiseParallel(
            input_layouts=Shard(1),
        )
    if hasattr(model, "score") and isinstance(model.score, nn.Module):
        # For PPO's critic model's score layer:
        # 1. The input is sharded by sequence parallelism (Shard(1))
        # 2. `score` is a linear layer with replicated weights
        # 3. All-gather the output along the sequence dimension to get the full results
        root_tp_plan["score"] = ReplicateParallel(
            input_layout=Shard(1),
            desired_input_layout=Shard(1),
            output_layout=Replicate(),
        )

    if is_valid_vision_model(model_config.model_type):
        if isinstance(model.model.language_model, nn.Module):
            # For vision-language models, avoid sharding the embedding layer because
            # the visual components access it without tensor parallelism support.
            # Instead, configure the first transformer layer to handle input
            # sharding properly.
            model_tp_plan.pop("embed_tokens", None)
            model_tp_plan["layers.0"] = PrepareModuleInput(
                input_layouts=Replicate(),
                desired_input_layouts=Shard(1),
            )

            # For Qwen3 VL, patch _deepstack_process for TP
            if is_qwen3_vl_model(model_config.model_type):
                # NOTE: Lazy import to avoid ImportError when qwen3_vl model is not used.
                # transformers.models.qwen3_vl doesn't exist in all transformers versions,
                # so we only import it when actually needed for Qwen3 VL models.
                from areal.models.transformers.qwen3_vl import (
                    patch_qwen3_vl_deepstack_process_for_tp,
                )

                patch_qwen3_vl_deepstack_process_for_tp(model.model.language_model)

            parallelize_module(
                model.model.language_model,
                device_mesh=tp_device_mesh,
                parallelize_plan=model_tp_plan,
            )
        else:
            raise RuntimeError(
                "Vision model does not have the required submodule 'model.language_model'"
            )
    else:
        parallelize_module(
            model.model,
            device_mesh=tp_device_mesh,
            parallelize_plan=model_tp_plan,
        )

    parallelize_module(
        model,
        device_mesh=tp_device_mesh,
        parallelize_plan=root_tp_plan,
    )

    if self.config.init_from_scratch or self.config.fsdp.memory_efficient_load:
        model = model_class.from_config(
            self.model_config,
            **model_kwargs,
        )
    else:
        model = model_class.from_pretrained(
            pretrained_model_name_or_path=self.config.path,
            trust_remote_code=True,
            **model_kwargs,
        )
    return model

def _create_device_model(self):
    current_platform.set_device(int(os.environ["LOCAL_RANK"]))
    current_platform.set_numa_affinity(int(os.environ["LOCAL_RANK"]))
    if current_platform.device_type == "cpu":
        self.device = torch.device("cpu")
    else:
        self.device = torch.device(int(os.environ["LOCAL_RANK"]))

    # Load weights in optimizer_dtype (typically fp32) to maintain
    # master weights. FSDP2 MP casts to compute dtype on-the-fly.
    dtype = getattr(torch, self.config.optimizer_dtype)

    if self.config.fsdp.memory_efficient_load:
        # Only rank 0 loads on CPU; other ranks use meta device (zero memory)
        # to avoid CPU OOM when multiple workers share a node.
        # Weights are broadcast from rank 0 after FSDP sharding in initialize().
        # Note: meta device optimization only applies to LLM (not VLM), because
        # VLM uses from_pretrained() which doesn't support meta device context.
        if not self.is_vision_model and dist.get_rank() != 0:
            loading_device = "meta"
        else:
            loading_device = "cpu"
    else:
        loading_device = current_platform.device_type

    self.get_device_stats().log("before model creation/loading")

    # Note: VLMs often have vision_tower in fp32 already; loading whole
    # model in optimizer_dtype (fp32 default) is consistent.
    if self.is_vision_model:
        # Compute dtype (config.dtype) is what FSDP2 MP casts to in
        # forward/backward; storage dtype (optimizer_dtype) is restricted
        # to fp32/bf16 by config validation, so checking it would never
        # catch a float16 misconfiguration.
        if self._compute_dtype() == torch.float16:
            raise ValueError(
                "Vision models do not support float16 dtype. Please use bfloat16."
            )
        if self.config.init_from_scratch:
            raise ValueError(
                "Vision models do not support initialization from scratch. Please use a pretrained model."
            )
        self.processor, self.tokenizer = load_hf_processor_and_tokenizer(
            self.config.path
        )

        tik = time.perf_counter()
        # VLM: Use from_pretrained() on loading_device.
        with torch.device(loading_device):
            model = AutoModelForImageTextToText.from_pretrained(
                pretrained_model_name_or_path=self.config.path,
                trust_remote_code=True,
                dtype=dtype,
                attn_implementation=self.config.attn_impl,
            )
            if self.config.disable_dropout:
                disable_dropout_in_model(model)
    else:
        self.tokenizer = load_hf_tokenizer(self.config.path)
        self.processor = None
        tik = time.perf_counter()
        # LLM: Decide between from_config() or from_pretrained() based on memory_efficient_load
        with torch.device(loading_device):
            model = self._create_llm_actor_or_critic()
            if self.config.disable_dropout:
                disable_dropout_in_model(model)

    self.get_device_stats().log("after model creation/loading")

    if self.config.gradient_checkpointing:
        model.gradient_checkpointing_enable(
            gradient_checkpointing_kwargs={"use_reentrant": False}
        )
    if self.config.use_kernels:
        model.use_kernels = True
    self.logger.info(
        f"Model creation and loading time: {time.perf_counter() - tik:.2f}s"
    )
    self.model = model

def _apply_peft_wrapper(self):
    config = self.config
    if not config.target_modules or config.target_modules == ["all-linear"]:
        target_modules = "all-linear"
    else:
        target_modules = config.target_modules
    peft_config = {
        "task_type": TaskType.CAUSAL_LM,
        "r": config.lora_rank,
        "lora_alpha": config.lora_alpha,
        "target_modules": target_modules,
        "bias": "none",
    }
    if self.config.peft_type == "lora":
        peft_config = LoraConfig(**peft_config)
    else:
        raise NotImplementedError()

    self.model.enable_input_require_grads()
    # autocast_adapter_dtype=False: with optimizer_dtype=float32, LoRA
    # adapter weights are stored in fp32 alongside the base model.
    # FSDP2 MixedPrecisionPolicy (param_dtype=config.dtype) casts both
    # base and adapter params to compute dtype during forward/backward.
    # The fp32 adapter path is not exercised by tests/test_fsdp_optimizer_dtype.py
    # (full-model only); LoRA + fp32 master is a known untested combination.
    self.model = get_peft_model(
        self.model,
        peft_config,
        autocast_adapter_dtype=False,
    )

    if self.rank == 0:
        self.model.print_trainable_parameters()

def _create_optimizer(self, ft_spec: FinetuneSpec) -> None:
    if self.optimizer_config is None:
        return
    assert self.model is not None
    # Set up optimizer
    tik = time.perf_counter()
    assert self.optimizer_config.type in [
        "adam",
        "adam_bf16",
        "sgd",
    ], "Only adam/adam_bf16/sgd optimizer is supported in this engine."
    if self.optimizer_config.type == "sgd":
        self.logger.warning(
            "Using SGD with FSDP may be less stable. Consider using "
            "the 'adam' (AdamW) optimizer for improved stability."
        )
    elif self.optimizer_config.type == "adam_bf16":
        if self.config.optimizer_dtype != "bfloat16":
            # __post_init__ canonicalizes bf16 → bfloat16; check canonical value only.
            self.logger.warning(
                "adam_bf16 is intended to be paired with optimizer_dtype="
                "'bfloat16' for memory savings (m/v in bf16, Kahan summation "
                "for fp32-equivalent updates). Current optimizer_dtype=%s — "
                "you may want to use the standard 'adam' optimizer instead.",
                self.config.optimizer_dtype,
            )
    elif (
        self.optimizer_config.type == "adam"
        and self.config.optimizer_dtype == "bfloat16"
    ):
        self.logger.warning(
            "optimizer.type='adam' with optimizer_dtype='bfloat16' is the "
            "exact configuration that triggers issue #1292 (silent loss "
            "plateau ~3x higher than fp32 master weights). torch.optim.AdamW "
            "will create bf16 exp_avg/exp_avg_sq inheriting from "
            "model.parameters(). For memory savings, switch to "
            "optimizer.type='adam_bf16' (uses Kahan summation). "
            "For default behavior, leave optimizer_dtype='float32'."
        )
    lr = self.optimizer_config.lr
    weight_decay = self.optimizer_config.weight_decay
    beta1 = self.optimizer_config.beta1
    beta2 = self.optimizer_config.beta2
    eps = self.optimizer_config.eps
    if self.optimizer_config.type == "adam":
        self.optimizer = torch.optim.AdamW(
            self.model.parameters(),
            lr=lr,
            weight_decay=weight_decay,
            betas=(beta1, beta2),
            eps=eps,
            # VLM with tensor parallelism is incompatible with fused AdamW
            fused=not (self.is_vision_model and self.parallel_helper.tp_enabled),
        )
    elif self.optimizer_config.type == "adam_bf16":
        self.optimizer = AnyPrecisionAdamW(
            self.model.parameters(),
            lr=lr,
            weight_decay=weight_decay,
            betas=(beta1, beta2),
            eps=eps,
            momentum_dtype="bfloat16",
            variance_dtype="bfloat16",
        )
    else:
        self.optimizer = torch.optim.SGD(
            self.model.parameters(),
            lr=lr,
            weight_decay=weight_decay,
        )
    total_train_steps = ft_spec.total_train_steps
    num_warmup_steps = int(
        self.optimizer_config.warmup_steps_proportion * total_train_steps
    )

    if self.optimizer_config.lr_scheduler_type == "cosine":
        self.lr_scheduler = get_cosine_schedule_with_warmup(
            self.optimizer,
            num_warmup_steps,
            total_train_steps,
            min_lr_ratio=self.optimizer_config.min_lr_ratio,
        )
    elif self.optimizer_config.lr_scheduler_type == "linear":
        self.lr_scheduler = get_linear_schedule_with_warmup(
            self.optimizer,
            num_warmup_steps,
            total_train_steps,
        )
    elif self.optimizer_config.lr_scheduler_type == "constant":
        self.lr_scheduler = get_constant_schedule_with_warmup(
            self.optimizer,
            num_warmup_steps,
        )
    else:
        raise ValueError(
            f"Unknown lr scheduler type {self.optimizer_config.lr_scheduler_type}"
        )
    self.logger.info(f"Create optimizer time: {time.perf_counter() - tik}")

def _check_rollout_engine_connected(self) -> None:
    """Validate that rollout engine has been connected via connect_engine()."""
    if self.rollout_engine is None or self.rollout_coordinator is None:
        raise RuntimeError(
            "Rollout engine not connected. Call connect_engine()"
            " before using rollout/update_weight methods."
        )

def _ensure_ready(self) -> None:
    if self.is_offload:
        self.onload()

    if self.parallel_helper.sp_size > 1:
        set_ulysses_sequence_parallel_group(self.sp_group)

