    elif cfg.type == "ray":
        return RayScheduler(exp_config=self.config)
    elif cfg.type == "slurm":
        return SlurmScheduler(exp_config=self.config)
    raise NotImplementedError(f"Unknown scheduler type: {cfg.type}")

